/* prog24_query_string_parser – reconstructed from the supplied binary
 *
 * The original program reads a line from stdin, treats it as a URL‑encoded
 * query string (key=value&key2=value2 …), decodes each key and value and
 * prints them as “key=value” lines.  If no line can be read it prints
 * “NO_INPUT”.
 *
 * The implementation below follows the same observable behaviour while
 * using clear, idiomatic C.
 */

#include <stdio.h>
#include <string.h>
#include <ctype.h>

#define MAX_LINE 2048          /* size of the input buffer               */
#define MAX_BUF  2048          /* size for decoded key/value buffers      */

/* ----------------------------------------------------------------------
 * URL‑decode a fragment.
 *
 *  src   – pointer to the encoded data
 *  len   – number of bytes to examine (may be less than strlen(src))
 *  dst   – buffer where the decoded string is written; it is NUL‑terminated
 *
 * The decoder implements the behaviour observed in the original binary:
 *   '+'  → space
 *   "%XY" where X and Y are hex digits → the byte with that value
 *   otherwise the character is copied unchanged.
 * ---------------------------------------------------------------------- */
static void url_decode(const char *src, size_t len, char *dst)
{
    size_t i = 0, o = 0;

    while (i < len) {
        char c = src[i];

        if (c == '+') {
            dst[o++] = ' ';
            ++i;
        } else if (c == '%' && i + 2 < len &&
                   isxdigit((unsigned char)src[i + 1]) &&
                   isxdigit((unsigned char)src[i + 2])) {
            /* convert two hex digits */
            char hi = src[i + 1];
            char lo = src[i + 2];
            int val = (isdigit((unsigned char)hi) ? hi - '0' :
                      (toupper((unsigned char)hi) - 'A' + 10));
            val = (val << 4) + (isdigit((unsigned char)lo) ? lo - '0' :
                      (toupper((unsigned char)lo) - 'A' + 10));
            dst[o++] = (char)val;
            i += 3;
        } else {
            dst[o++] = c;
            ++i;
        }
    }
    dst[o] = '\0';
}

/* ----------------------------------------------------------------------
 * Main program – parses a single line from stdin.
 * ---------------------------------------------------------------------- */
int main(void)
{
    static char line[MAX_LINE];
    static char key[MAX_BUF];
    static char val[MAX_BUF];

    /* read a line; the original binary used fgets with size 0x800 */
    if (fgets(line, sizeof(line), stdin) == NULL) {
        puts("NO_INPUT");
        return 0;
    }

    /* Strip trailing newline and optional carriage‑return */
    size_t len = strlen(line);
    if (len && line[len - 1] == '\n') {
        line[--len] = '\0';
    }
    if (len && line[len - 1] == '\r') {
        line[--len] = '\0';
    }

    /* Walk through the query string, tokenising on '&' */
    const char *p = line;
    while (*p) {
        /* locate the end of the current token */
        const char *token_end = strchr(p, '&');
        if (!token_end) token_end = p + strlen(p);   /* last token */

        /* find the first '=' inside the token, if any */
        const char *eq = memchr(p, '=', (size_t)(token_end - p));

        if (eq) {
            /* key = [p, eq)   value = (eq+1, token_end) */
            url_decode(p, (size_t)(eq - p), key);
            url_decode(eq + 1, (size_t)(token_end - (eq + 1)), val);
        } else {
            /* No '=', value is empty */
            url_decode(p, (size_t)(token_end - p), key);
            val[0] = '\0';
        }

        printf("%s=%s\n", key, val);

        /* advance to the next token (skip the '&' if present) */
        p = (*token_end == '&') ? token_end + 1 : token_end;
    }

    return 0;
}
